const APP_VERSION = "2.0.0";
const STORAGE_KEY = "motorclaro-state";
const VEHICLES = {
  SEAT:{Ibiza:[2000,2026],León:[2000,2026],Toledo:[2000,2019],Ateca:[2016,2026],Arona:[2017,2026]},
  Volkswagen:{Golf:[2000,2026],Polo:[2000,2026],Passat:[2000,2026],Touran:[2003,2026],Tiguan:[2007,2026]},
  Renault:{Clio:[2000,2026],Mégane:[2000,2026],Scénic:[2000,2026],Captur:[2013,2026]},
  Hyundai:{i20:[2008,2026],i30:[2007,2026],Tucson:[2004,2026]},
  Ford:{Fiesta:[2000,2023],Focus:[2000,2026],Mondeo:[2000,2022],"C-Max":[2003,2019],Kuga:[2008,2026]},
  Opel:{Corsa:[2000,2026],Astra:[2000,2026],Zafira:[2000,2026],Insignia:[2008,2022]}
};
const FUELS={gasoline:"Gasolina",diesel:"Diésel",mhev:"Microhíbrido 48 V",hybrid:"Híbrido",phev:"Híbrido enchufable",electric:"Eléctrico",lpg:"GLP/bifuel",other:"Otro"};
const COMPONENT_LABELS={directInjection:"Inyección directa",commonRail:"Common-rail",turbo:"Turbo",lambda:"Sondas lambda",catalyst:"Catalizador",gpf:"Filtro GPF",egr:"EGR",dpf:"Filtro DPF",scr:"SCR",adblue:"AdBlue",timingChain:"Cadena de distribución",startStop:"Start/Stop",dct:"Doble embrague",mhev48:"Sistema 48 V",mhsg:"Motor-generador MHSG",dcDc:"Convertidor DC/DC",abs:"ABS",esc:"Control de estabilidad",eps:"Dirección eléctrica",ac:"Climatización",tpms:"TPMS",portInjection:"Inyección indirecta",hybridSystem:"Sistema híbrido",plugIn:"Carga enchufable",tractionBattery:"Batería de tracción",electricDrive:"Tracción eléctrica",cvt:"Transmisión CVT/multimodo",automaticGearbox:"Cambio automático",lpg:"Sistema GLP"};
const VARIANTS=globalThis.VEHICLE_VARIANTS||[];
const DIAG=globalThis.MOTORCLARO_DIAG||{faults:{},symptoms:[],questions:[],genericObd:{}};
const MODEL_YEAR_GAPS={"SEAT|Toledo":[2010,2011]};
const main=document.querySelector("#main"),sheet=document.querySelector("#sheet"),sheetContent=document.querySelector("#sheetContent"),toast=document.querySelector("#toast"),importFile=document.querySelector("#importFile");
let state=loadState(),currentView="home",diagnosis=null,installPrompt=null,lastFocus=null;

function defaults(){return{version:2,profile:{name:""},vehicles:[],maintenanceRecords:[],diagnosisHistory:[],selectedVehicleId:null,settings:{theme:"auto",accent:"lime"}}}
function migrate(raw){
  const base=defaults(); if(!raw||typeof raw!=="object"||Array.isArray(raw))return base;
  base.profile={name:String(raw.profile?.name||"").slice(0,40)};
  base.vehicles=Array.isArray(raw.vehicles)?raw.vehicles.filter(v=>v&&v.id&&v.brand&&v.model).map(v=>({...v,year:Number(v.year)||new Date().getFullYear(),power:Number(v.power)||0,mileage:Number(v.mileage)||0,tech:Array.isArray(v.tech)?v.tech:[]})):[];
  base.maintenanceRecords=Array.isArray(raw.maintenanceRecords)?raw.maintenanceRecords:[];
  if(raw.maintenance&&typeof raw.maintenance==="object")Object.entries(raw.maintenance).forEach(([vehicleId,items])=>Object.entries(items||{}).forEach(([taskId,done])=>{if(done)base.maintenanceRecords.push({id:id(),vehicleId,taskId,date:new Date().toISOString().slice(0,10),mileage:null,notes:"Migrado desde MotorClaro v1",cost:null})}));
  base.diagnosisHistory=Array.isArray(raw.diagnosisHistory)?raw.diagnosisHistory:[];
  base.vehicles.forEach(v=>{if(v.lastDiagnosis&&!base.diagnosisHistory.some(d=>d.vehicleId===v.id)){base.diagnosisHistory.push({id:id(),vehicleId:v.id,date:v.lastDiagnosis.date||new Date().toISOString(),symptom:"Diagnóstico v1",results:v.lastDiagnosis.results||[],answers:[],notes:"Migrado desde MotorClaro v1"})}});
  base.selectedVehicleId=base.vehicles.some(v=>v.id===raw.selectedVehicleId)?raw.selectedVehicleId:base.vehicles[0]?.id||null;
  base.settings={...base.settings,...(raw.settings||{})}; return base;
}
function loadState(){try{return migrate(JSON.parse(localStorage.getItem(STORAGE_KEY)))}catch{return defaults()}}
function saveState(message=""){try{state.version=2;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(message)showToast(message);return true}catch{showToast("No se pudo guardar. Exporta una copia y revisa el almacenamiento.");return false}}
function id(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`}
function esc(v=""){return String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c])}
function fmtDate(v){if(!v)return"—";const d=new Date(v.length===10?`${v}T12:00:00`:v);return Number.isNaN(d.valueOf())?"—":new Intl.DateTimeFormat("es-ES",{day:"2-digit",month:"short",year:"numeric"}).format(d)}
function fmtNumber(v){return new Intl.NumberFormat("es-ES").format(Number(v)||0)}
function greeting(){const h=new Date().getHours();return h<12?"Buenos días":h<20?"Buenas tardes":"Buenas noches"}
function yearsForModel(brand,model){const [min,max]=VEHICLES[brand][model],gaps=new Set(MODEL_YEAR_GAPS[`${brand}|${model}`]||[]);return Array.from({length:max-min+1},(_,i)=>max-i).filter(y=>!gaps.has(y))}
function variantsFor(brand,model,year,fuel=""){return VARIANTS.filter(v=>v.brand===brand&&v.model===model&&Number(year)>=v.years[0]&&Number(year)<=v.years[1]&&(!fuel||v.fuel===fuel))}
function selectedVehicle(){return state.vehicles.find(v=>v.id===state.selectedVehicleId)||state.vehicles[0]||null}
function vehicleName(v){return v.nickname||`${v.brand} ${v.model}`}
function vehicleDetails(v){return`${v.year} · ${FUELS[v.fuel]||v.fuel||"Sin combustible"} · ${v.power||"—"} CV · ${v.gearbox||(v.transmission==="automatic"?"Automático":"Manual")}`}
function baseFuel(v){return v.baseFuel||(v.fuel==="mhev"?"gasoline":v.fuel)}
function tagsFor(v){const tags=new Set(["all",v.fuel,baseFuel(v),v.transmission]);if(v.fuel!=="electric")tags.add("combustion");if(v.turbo==="yes")tags.add("turbo");(v.tech||[]).forEach(t=>tags.add(t));return tags}
function componentsFor(v){return[...(new Set(v.tech||[]))].filter(k=>COMPONENT_LABELS[k]).map(k=>COMPONENT_LABELS[k])}
function applyTheme(){const theme=state.settings.theme||"auto",dark=theme==="dark"||(theme==="auto"&&matchMedia("(prefers-color-scheme: dark)").matches);document.documentElement.dataset.theme=dark?"dark":"light"}
function setView(view){currentView=view;diagnosis=view==="diagnosis"?diagnosis:null;document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.view===view));render();main.focus({preventScroll:true});scrollTo({top:0,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}
function render(){document.querySelector("#profileButton").textContent=(state.profile.name||"A").slice(0,1).toUpperCase();({home:renderHome,garage:renderGarage,diagnosis:renderDiagnosis,maintenance:renderMaintenance,history:renderHistory}[currentView]||renderHome)()}

function installExperience(){
  const standalone=matchMedia("(display-mode: standalone)").matches||navigator.standalone===true;if(standalone)return"";
  if(/iphone|ipad|ipod/i.test(navigator.userAgent))return`<div class="install-card"><span>↗</span><div><strong>Instalar en iPhone o iPad</strong><small>Compartir → Añadir a pantalla de inicio.</small></div></div>`;
  if(installPrompt)return`<div class="install-card"><span>↓</span><div><strong>Instalar MotorClaro</strong><small>Úsala como app y también sin conexión.</small></div><button data-action="install">Instalar</button></div>`;return"";
}
function renderHome(){const car=selectedVehicle(),due=car?maintenancePlan(car).filter(x=>dueStatus(car,x).status==="overdue").length:0;main.innerHTML=`
  <section class="hero"><div class="status-pill">Datos guardados en este dispositivo</div><p class="eyebrow">${greeting()}</p><h1>${state.profile.name?esc(state.profile.name):"Tu coche, más claro."}</h1><p class="hero-copy">Diagnóstico guiado con triaje de seguridad, historial de mantenimiento y consulta de códigos OBD.</p></section>
  <section class="quick-grid"><button class="quick-card primary" data-action="diagnose"><span class="quick-icon">✦</span><strong>Revisar un problema</strong><small>Formulario detallado y resultados razonados</small></button><button class="quick-card" data-action="add-car"><span class="quick-icon">＋</span><strong>Añadir coche</strong><small>Catálogo, VIN o configuración manual</small></button></section>
  ${installExperience()}<div class="summary-grid"><div class="summary-card"><strong>${state.vehicles.length}</strong><small>vehículos</small></div><div class="summary-card"><strong>${state.diagnosisHistory.length}</strong><small>diagnósticos</small></div><div class="summary-card"><strong>${state.maintenanceRecords.length}</strong><small>servicios</small></div><div class="summary-card"><strong>${due}</strong><small>pendientes</small></div></div>
  <div class="section-head"><div><h2>Tu garaje</h2><p>${car?`Seleccionado: ${esc(vehicleName(car))}`:"Añade el primer vehículo"}</p></div><button class="text-button" data-action="garage">Ver todos</button></div>
  ${state.vehicles.length?`<div class="car-list">${state.vehicles.slice(0,2).map(carCard).join("")}</div>`:emptyGarage()}
  <div class="notice danger"><span>!</span><div><strong>Primero, la seguridad</strong>Con testigo rojo, frenos deficientes, olor a combustible, humo intenso o sobrecalentamiento, detén el coche y pide asistencia.</div></div>`;bindCommon()}
function carCard(v){return`<button class="car-card" data-vehicle="${esc(v.id)}"><span class="car-icon" aria-hidden="true">▰</span><span><strong>${esc(vehicleName(v))}</strong><small>${esc(v.nickname?`${v.brand} ${v.model} · ${vehicleDetails(v)}`:vehicleDetails(v))}</small></span><span class="chevron" aria-hidden="true">›</span></button>`}
function emptyGarage(){return`<div class="empty-card"><div class="empty-icon" aria-hidden="true">▰</div><h3>Tu garaje está vacío</h3><p class="muted">Añade un coche para adaptar preguntas, averías y mantenimiento.</p><button class="button" data-action="add-car">Añadir mi primer coche</button></div>`}
function renderGarage(){main.innerHTML=`<p class="eyebrow">Vehículos y datos técnicos</p><h1>Garaje</h1><p class="hero-copy">Puedes editar, actualizar kilómetros, identificar por VIN y consultar la vía oficial de matrícula.</p><div class="section-head"><h2>${state.vehicles.length||"Sin"} ${state.vehicles.length===1?"coche":"coches"}</h2></div>${state.vehicles.length?`<div class="car-list">${state.vehicles.map(carCard).join("")}</div><button class="floating-add" data-action="add-car">＋ Añadir otro coche</button>`:emptyGarage()}<button class="floating-add" data-action="identify">⌕ Identificar por VIN o matrícula</button>`;bindCommon()}

function renderDiagnosis(){
  const car=selectedVehicle();if(!car){main.innerHTML=`<p class="eyebrow">Asistente mecánico</p><h1>Diagnóstico</h1><div class="empty-card" style="margin-top:24px"><h3>Primero añade un coche</h3><p class="muted">Así evitamos preguntas y causas incompatibles.</p><button class="button" data-action="add-car">Añadir coche</button></div>`;bindCommon();return}
  if(diagnosis?.stage==="details")return renderDiagnosisDetails();if(diagnosis?.stage==="questions")return renderQuestion();if(diagnosis?.stage==="results")return renderResults();
  const tags=tagsFor(car);const symptoms=DIAG.symptoms.filter(s=>!(s.id==="smoke"&&car.fuel==="electric")&&!(s.id==="gearbox"&&!tags.has("manual")&&!tags.has("automatic")));
  main.innerHTML=`<section class="diag-intro"><div class="vehicle-chip">▰ ${esc(vehicleName(car))} · ${esc(String(car.year))}</div><h1>¿Qué notas?</h1><p>La app cruza síntomas, contexto, códigos OBD y sistemas compatibles. No sustituye una diagnosis con mediciones.</p></section><div class="section-head"><div><h2>Síntoma principal</h2><p>Después podrás describirlo con detalle.</p></div></div><div class="symptom-grid">${symptoms.map(s=>`<button class="symptom-card" data-symptom="${s.id}"><span>${esc(s.short)}</span><strong>${esc(s.label)}</strong></button>`).join("")}</div><button class="text-button" data-action="change-car" style="margin-top:18px">Cambiar vehículo</button>`;
  main.querySelectorAll("[data-symptom]").forEach(b=>b.onclick=()=>{diagnosis={stage:"details",symptom:b.dataset.symptom,answers:[],scores:{},context:{},index:0,critical:false};renderDiagnosis()});main.querySelector("[data-action='change-car']").onclick=openVehiclePicker;
}
function renderDiagnosisDetails(){const s=DIAG.symptoms.find(x=>x.id===diagnosis.symptom);main.innerHTML=`<button class="text-button" data-action="cancel-diag">‹ Cambiar síntoma</button><p class="eyebrow">Contexto del fallo</p><h1>${esc(s?.label||"Diagnóstico")}</h1><p class="hero-copy">Cuanto más preciso seas, menos posibilidades irrelevantes saldrán.</p><form id="diagDetails" class="form-grid">
  <div class="two-cols"><label class="field"><span>Gravedad</span><select name="severity"><option value="mild">Leve</option><option value="medium">Media</option><option value="strong">Fuerte</option><option value="unsafe">No parece seguro circular</option></select></label><label class="field"><span>Frecuencia</span><select name="frequency"><option value="once">Una vez</option><option value="intermittent">Intermitente</option><option value="often">Frecuente</option><option value="constant">Constante</option></select></label></div>
  <div class="two-cols"><label class="field"><span>Cuándo empezó</span><select name="onset"><option value="sudden">De golpe</option><option value="gradual">Poco a poco</option><option value="after-work">Tras reparación/batería/golpe</option><option value="unknown">No lo sé</option></select></label><label class="field"><span>Motor/vehículo</span><select name="temperature"><option value="any">En cualquier momento</option><option value="cold">En frío</option><option value="hot">En caliente</option><option value="city">Parado o ciudad</option><option value="road">En carretera</option></select></label></div>
  <label class="field"><span>Códigos OBD separados por espacios o comas</span><input name="obd" maxlength="120" placeholder="Ej. P0301, P0299"></label>
  <div class="check-list"><label class="check-row"><input type="checkbox" name="redWarning"><span><strong>Hay un testigo rojo</strong><small class="muted">Aceite, temperatura, frenos o sistema eléctrico crítico.</small></span></label><label class="check-row"><input type="checkbox" name="fuelSmell"><span><strong>Huele a combustible o hay fuga</strong></span></label><label class="check-row"><input type="checkbox" name="brakeDanger"><span><strong>El coche no frena bien o el pedal se hunde</strong></span></label><label class="check-row"><input type="checkbox" name="overheat"><span><strong>Temperatura en rojo, vapor o pérdida de refrigerante</strong></span></label><label class="check-row"><input type="checkbox" name="hvDanger"><span><strong>Humo, olor químico o calor en batería híbrida/eléctrica</strong></span></label></div>
  <label class="field"><span>Describe cualquier detalle adicional</span><textarea name="notes" maxlength="600" placeholder="Ruido, olor, zona, velocidad, qué estabas haciendo..."></textarea></label><button class="button accent">Empezar preguntas</button></form>`;
  main.querySelector("[data-action='cancel-diag']").onclick=()=>{diagnosis=null;renderDiagnosis()};main.querySelector("#diagDetails").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);diagnosis.context=Object.fromEntries(fd);diagnosis.context.flags=["redWarning","fuelSmell","brakeDanger","overheat","hvDanger"].filter(k=>fd.has(k));diagnosis.critical=diagnosis.context.severity==="unsafe"||diagnosis.context.flags.length>0;diagnosis.questions=questionsForDiagnosis();seedContextScores();diagnosis.stage="questions";renderDiagnosis()};
}
function questionsForDiagnosis(){const tags=tagsFor(selectedVehicle());return DIAG.questions.filter(q=>(q.symptom===diagnosis.symptom||q.symptom==="all")&&q.systems.some(t=>tags.has(t)))}
function seedContextScores(){const c=diagnosis.context;if(c.severity==="strong")diagnosis.scores.genericSensor=2;if(c.frequency==="constant")diagnosis.scores.genericSensor=(diagnosis.scores.genericSensor||0)+2;if(c.onset==="after-work"){diagnosis.scores.ground=3;diagnosis.scores.software=2}if(c.flags.includes("fuelSmell"))diagnosis.scores.fuelLeak=14;if(c.flags.includes("brakeDanger"))diagnosis.scores.brakeFluid=14;if(c.flags.includes("overheat")){diagnosis.scores.coolantLeak=12;diagnosis.scores.waterPump=10}if(c.flags.includes("hvDanger"))diagnosis.scores.hvBattery=15;if(c.flags.includes("redWarning"))diagnosis.scores.genericSensor=5;applyObdScores(c.obd||"")}
function applyObdScores(text){const codes=[...new Set(String(text).toUpperCase().match(/[PBCU][0-9A-F]{4}/g)||[])];diagnosis.obdCodes=codes;for(const code of codes){if(/^P030/.test(code))diagnosis.scores.coils=(diagnosis.scores.coils||0)+10;if(code==="P0299")diagnosis.scores.turboLeak=(diagnosis.scores.turboLeak||0)+10;if(code==="P0420")diagnosis.scores.catalyst=(diagnosis.scores.catalyst||0)+10;if(["P2002","P2453","P2463"].includes(code))diagnosis.scores.dpf=(diagnosis.scores.dpf||0)+10;if(code==="P20E8")diagnosis.scores.adblue=(diagnosis.scores.adblue||0)+10;if(/^U/.test(code))diagnosis.scores.software=(diagnosis.scores.software||0)+6;if(/^C/.test(code))diagnosis.scores.absSensor=(diagnosis.scores.absSensor||0)+4}}
function renderQuestion(){const qs=diagnosis.questions,item=qs[diagnosis.index],progress=((diagnosis.index+1)/qs.length)*100;if(!item){diagnosis.stage="results";return renderResults()}main.innerHTML=`<button class="text-button" data-action="back-question">‹ ${diagnosis.index?"Pregunta anterior":"Volver al contexto"}</button><div class="progress-track"><div class="progress-bar" style="width:${progress}%"></div></div><span class="question-count">PREGUNTA ${diagnosis.index+1} DE ${qs.length}</span><h2 class="question-title">${esc(item.text)}</h2><div class="answer-list">${item.answers.map((a,i)=>`<button class="answer" data-answer="${i}">${esc(a.label)}</button>`).join("")}</div>`;
  main.querySelector("[data-action='back-question']").onclick=()=>{if(!diagnosis.index){diagnosis.stage="details";diagnosis.answers=[];diagnosis.scores={};renderDiagnosis();return}diagnosis.answers.pop();diagnosis.index--;recomputeScores();renderQuestion()};main.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>{const ans=item.answers[Number(b.dataset.answer)];diagnosis.answers.push({questionId:item.id,question:item.text,answer:ans.label,scores:ans.scores,flags:ans.flags});if(ans.flags.includes("critical"))diagnosis.critical=true;diagnosis.index++;recomputeScores();if(diagnosis.index>=qs.length)diagnosis.stage="results";renderDiagnosis()})
}
function recomputeScores(){diagnosis.scores={};diagnosis.critical=diagnosis.context.severity==="unsafe"||diagnosis.context.flags.length>0;seedContextScores();diagnosis.answers.forEach(a=>{Object.entries(a.scores||{}).forEach(([k,v])=>diagnosis.scores[k]=(diagnosis.scores[k]||0)+v);if((a.flags||[]).includes("critical"))diagnosis.critical=true})}
function diagnosticResults(){const tags=tagsFor(selectedVehicle());return Object.entries(diagnosis.scores).filter(([k,score])=>score>0&&DIAG.faults[k]&&DIAG.faults[k].systems.some(t=>tags.has(t))).map(([key,score])=>({key,score,...DIAG.faults[key]})).sort((a,b)=>(b.stop-a.stop)||(b.score-a.score)||(urgencyRank(b.urgency)-urgencyRank(a.urgency)))}
function urgencyRank(u){return({informativa:0,baja:1,media:2,alta:3,crítica:4})[u]||0}
function confidenceLabel(score,max){const r=score/Math.max(max,1);return r>=.72?"Coincidencia alta":r>=.42?"Coincidencia media":"Coincidencia baja"}
function renderResults(){let results=diagnosticResults();if(!results.length)results=[{key:"genericSensor",score:1,...DIAG.faults.genericSensor}];const top=results.slice(0,8),critical=diagnosis.critical||top.some(r=>r.stop),max=top[0].score;main.innerHTML=`<p class="eyebrow">Resultado orientativo</p><h1>${critical?"Primero: no te la juegues":"Posibles causas"}</h1><p class="hero-copy">Se han valorado ${Object.keys(DIAG.faults).length} causas y se muestran ${top.length} compatibles con ${esc(vehicleName(selectedVehicle()))}. La coincidencia no es una probabilidad.</p>${critical?`<div class="alert danger"><span>!</span><div><strong>Puede no ser seguro circular</strong>Apaga el vehículo si hay testigo rojo, fuga, sobrecalentamiento, frenos deficientes, humo u olor químico. Pide asistencia si la señal continúa.</div></div>`:""}<div style="margin-top:22px">${top.map((r,i)=>`<article class="result-card ${r.stop?"critical":""}"><div class="result-top"><div><p class="eyebrow">${i+1}. ${esc(r.urgency)}</p><h3>${esc(r.name)}</h3></div><div class="confidence">${confidenceLabel(r.score,max)}</div></div><p>${esc(r.desc)}</p><span class="urgency ${esc(r.urgency)}">Prioridad ${esc(r.urgency)}</span><details><summary>Qué revisar</summary><p>${esc(r.checks)}</p></details></article>`).join("")}</div>${diagnosis.obdCodes?.length?`<div class="setting-card"><h3>Códigos OBD introducidos</h3><table class="data-table">${diagnosis.obdCodes.map(c=>`<tr><th>${esc(c)}</th><td>${esc(DIAG.genericObd[c]||"Código específico o no incluido: confirmar con documentación del fabricante")}</td></tr>`).join("")}</table></div>`:""}${results.length>8?`<details class="setting-card"><summary>Ver otras ${results.length-8} posibilidades compatibles</summary><div class="stack" style="margin-top:12px">${results.slice(8).map(r=>`<div><strong>${esc(r.name)}</strong><small class="muted">Coincidencia baja · prioridad ${esc(r.urgency)}</small></div>`).join("")}</div></details>`:""}<div class="notice info"><span>i</span><div><strong>Para confirmar una avería</strong>Hace falta inspección, lectura de datos en vivo y mediciones. No cambies piezas basándote solo en esta lista.</div></div><div class="button-row"><button class="button ghost" data-action="restart">Empezar de nuevo</button><button class="button" data-action="save-diagnosis">Guardar en historial</button></div>`;
  main.querySelector("[data-action='restart']").onclick=()=>{diagnosis=null;renderDiagnosis()};main.querySelector("[data-action='save-diagnosis']").onclick=()=>saveDiagnosis(top)
}
function saveDiagnosis(results){const record={id:id(),vehicleId:selectedVehicle().id,date:new Date().toISOString(),mileage:selectedVehicle().mileage,symptom:DIAG.symptoms.find(s=>s.id===diagnosis.symptom)?.label||diagnosis.symptom,context:diagnosis.context,obdCodes:diagnosis.obdCodes||[],answers:diagnosis.answers.map(({question,answer})=>({question,answer})),results:results.map(r=>({key:r.key,name:r.name,urgency:r.urgency,confidence:confidenceLabel(r.score,results[0].score)}))};state.diagnosisHistory.unshift(record);saveState("Diagnóstico guardado");main.querySelector("[data-action='save-diagnosis']").disabled=true}

const BASE_MAINT=[{id:"tyres",name:"Neumáticos y presiones",km:10000,months:6},{id:"brakes",name:"Frenos",km:20000,months:12},{id:"brakefluid",name:"Líquido de frenos",km:null,months:24},{id:"cabin",name:"Filtro de habitáculo",km:20000,months:12}];
function maintenancePlan(v){const items=[...BASE_MAINT];if(v.fuel!=="electric")items.unshift({id:"oil",name:"Aceite y filtro",km:15000,months:12});if(v.fuel!=="electric")items.push({id:"air",name:"Filtro de aire",km:30000,months:24});if(baseFuel(v)==="diesel")items.push({id:"fuel",name:"Filtro de combustible",km:40000,months:24});if(baseFuel(v)==="gasoline")items.push({id:"spark",name:"Bujías",km:60000,months:48});if((v.tech||[]).includes("dct")||v.transmission==="automatic")items.push({id:"gearbox",name:"Aceite de transmisión",km:60000,months:48});if((v.tech||[]).includes("dpf"))items.push({id:"dpf",name:"DPF y emisiones",km:30000,months:12});if(["electric","hybrid","phev","mhev"].includes(v.fuel))items.push({id:"hv",name:"Sistema electrificado",km:30000,months:24});items.push({id:"coolant",name:"Refrigerante y manguitos",km:30000,months:24},{id:"battery",name:"Batería de 12 V",km:null,months:12});return items}
function lastRecord(vehicleId,taskId){return state.maintenanceRecords.filter(r=>r.vehicleId===vehicleId&&r.taskId===taskId).sort((a,b)=>new Date(b.date)-new Date(a.date))[0]||null}
function dueStatus(v,item){const last=lastRecord(v.id,item.id);if(!last)return{status:"due",label:"Sin registrar"};const kmDue=item.km&&last.mileage!=null&&v.mileage>=Number(last.mileage)+item.km;const dateDue=item.months&&new Date()>=new Date(new Date(last.date).setMonth(new Date(last.date).getMonth()+item.months));if(kmDue||dateDue)return{status:"overdue",label:"Toca revisar"};const next=[];if(item.km&&last.mileage!=null)next.push(`${fmtNumber(Number(last.mileage)+item.km)} km`);if(item.months){const d=new Date(last.date);d.setMonth(d.getMonth()+item.months);next.push(fmtDate(d.toISOString()))}return{status:"ok",label:`Próximo: ${next.join(" o ")}`}}
function renderMaintenance(){const car=selectedVehicle();if(!car){main.innerHTML=`<p class="eyebrow">Mantenimiento</p><h1>Cuidados</h1>${emptyGarage()}`;bindCommon();return}const plan=maintenancePlan(car);main.innerHTML=`<p class="eyebrow">Plan por fecha y kilometraje</p><h1>Cuidados</h1><p class="hero-copy">Los intervalos son conservadores y editables al registrar cada servicio. Confirma siempre el manual de tu motor.</p><div class="vehicle-tabs" style="margin-top:22px">${state.vehicles.map(v=>`<button class="vehicle-tab ${v.id===car.id?"active":""}" data-maint-car="${esc(v.id)}">${esc(vehicleName(v))}</button>`).join("")}</div><div class="section-head"><div><h2>${esc(vehicleName(car))}</h2><p>${fmtNumber(car.mileage)} km</p></div><button class="text-button" data-update-mileage>Actualizar km</button></div>${plan.map(item=>{const due=dueStatus(car,item),last=lastRecord(car.id,item.id);return`<article class="maint-card"><div class="maint-icon" aria-hidden="true">${due.status==="ok"?"✓":"⚙"}</div><div><strong>${esc(item.name)}</strong><small>${last?`Último: ${fmtDate(last.date)}${last.mileage!=null?` · ${fmtNumber(last.mileage)} km`:""}`:"Todavía no hay un servicio registrado"}</small><small>${esc(due.label)}</small></div><button class="button small ghost" data-service="${item.id}">Registrar</button><span class="maint-tag ${due.status==="overdue"?"overdue":""}">${due.status==="ok"?"AL DÍA":due.status==="overdue"?"PENDIENTE":"REGISTRAR"}</span></article>`}).join("")}<div class="notice info"><span>i</span><div><strong>Intervalos orientativos</strong>MotorClaro no sustituye el plan oficial por VIN/código de motor. Si tu manual indica otro plazo, usa el del fabricante.</div></div>`;main.querySelectorAll("[data-maint-car]").forEach(b=>b.onclick=()=>{state.selectedVehicleId=b.dataset.maintCar;saveState();renderMaintenance()});main.querySelectorAll("[data-service]").forEach(b=>b.onclick=()=>openServiceForm(car,b.dataset.service));main.querySelector("[data-update-mileage]").onclick=()=>openMileageForm(car)}
function openServiceForm(car,taskId){const item=maintenancePlan(car).find(x=>x.id===taskId);openSheet(`<h2 id="sheetTitle">Registrar mantenimiento</h2><p class="muted">${esc(item.name)} · ${esc(vehicleName(car))}</p><form id="serviceForm" class="form-grid"><div class="two-cols"><label class="field"><span>Fecha</span><input required type="date" name="date" value="${new Date().toISOString().slice(0,10)}"></label><label class="field"><span>Kilometraje</span><input required type="number" min="0" max="3000000" name="mileage" value="${car.mileage}"></label></div><div class="two-cols"><label class="field"><span>Coste (€)</span><input type="number" min="0" step="0.01" name="cost" placeholder="Opcional"></label><label class="field"><span>Taller</span><input name="workshop" maxlength="80" placeholder="Opcional"></label></div><label class="field"><span>Notas, piezas o referencia</span><textarea name="notes" maxlength="600"></textarea></label><button class="button accent">Guardar servicio</button></form>`);sheetContent.querySelector("#serviceForm").onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));state.maintenanceRecords.unshift({id:id(),vehicleId:car.id,taskId,date:d.date,mileage:Number(d.mileage),cost:d.cost?Number(d.cost):null,workshop:d.workshop.trim(),notes:d.notes.trim()});car.mileage=Math.max(car.mileage,Number(d.mileage));saveState("Servicio guardado");closeSheet();renderMaintenance()}}
function openMileageForm(car){openSheet(`<h2 id="sheetTitle">Actualizar kilometraje</h2><form id="mileageForm" class="form-grid"><label class="field"><span>Kilómetros actuales</span><input autofocus required type="number" min="${car.mileage}" max="3000000" name="mileage" value="${car.mileage}"></label><button class="button accent">Actualizar</button></form>`);sheetContent.querySelector("#mileageForm").onsubmit=e=>{e.preventDefault();car.mileage=Number(new FormData(e.target).get("mileage"));saveState("Kilometraje actualizado");closeSheet();renderMaintenance()}}

function renderHistory(){const all=[...state.diagnosisHistory.map(x=>({...x,type:"diag"})),...state.maintenanceRecords.map(x=>({...x,type:"service"}))].sort((a,b)=>new Date(b.date)-new Date(a.date));main.innerHTML=`<p class="eyebrow">Todo lo que has guardado</p><h1>Historial</h1><p class="hero-copy">Diagnósticos, respuestas y mantenimientos ordenados por fecha.</p><div class="section-head"><h2>${all.length} registros</h2></div>${all.length?all.map(r=>{const car=state.vehicles.find(v=>v.id===r.vehicleId);if(r.type==="diag")return`<article class="history-card"><p class="eyebrow">Diagnóstico · ${fmtDate(r.date)}</p><h3>${esc(r.symptom)}</h3><small>${esc(car?vehicleName(car):"Vehículo eliminado")} ${r.mileage!=null?`· ${fmtNumber(r.mileage)} km`:""}</small><p>${esc(r.results?.[0]?.name||"Sin resultado")}</p><button class="text-button" data-history="${esc(r.id)}">Ver detalle</button></article>`;const task=car&&maintenancePlan(car).find(x=>x.id===r.taskId);return`<article class="history-card"><p class="eyebrow">Mantenimiento · ${fmtDate(r.date)}</p><h3>${esc(task?.name||r.taskId)}</h3><small>${esc(car?vehicleName(car):"Vehículo eliminado")} ${r.mileage!=null?`· ${fmtNumber(r.mileage)} km`:""}</small>${r.cost!=null?`<p>${new Intl.NumberFormat("es-ES",{style:"currency",currency:"EUR"}).format(r.cost)}</p>`:""}<button class="text-button" data-service-history="${esc(r.id)}">Ver detalle</button></article>`}).join(""): `<div class="empty-card"><h3>Aún no hay historial</h3><p class="muted">Guarda un diagnóstico o registra un mantenimiento.</p></div>`}`;main.querySelectorAll("[data-history]").forEach(b=>b.onclick=()=>openDiagnosisHistory(b.dataset.history));main.querySelectorAll("[data-service-history]").forEach(b=>b.onclick=()=>openServiceHistory(b.dataset.serviceHistory))}
function openDiagnosisHistory(idv){const r=state.diagnosisHistory.find(x=>x.id===idv);if(!r)return;openSheet(`<h2 id="sheetTitle">${esc(r.symptom)}</h2><p class="muted">${fmtDate(r.date)} · ${r.mileage!=null?`${fmtNumber(r.mileage)} km`:"Sin kilometraje"}</p>${r.obdCodes?.length?`<p><strong>OBD:</strong> ${esc(r.obdCodes.join(", "))}</p>`:""}<div class="selector-list">${(r.results||[]).map(x=>`<div class="selector-card"><strong>${esc(x.name)}</strong><small>${esc(x.confidence||"")} · prioridad ${esc(x.urgency||"—")}</small></div>`).join("")}</div><details><summary>Respuestas</summary><div class="stack">${(r.answers||[]).map(a=>`<p><strong>${esc(a.question)}</strong><br>${esc(a.answer)}</p>`).join("")}</div></details><button class="button danger" style="margin-top:18px" data-delete-history>Eliminar registro</button>`);sheetContent.querySelector("[data-delete-history]").onclick=()=>{if(!confirm("¿Eliminar este diagnóstico?"))return;state.diagnosisHistory=state.diagnosisHistory.filter(x=>x.id!==idv);saveState("Registro eliminado");closeSheet();renderHistory()}}
function openServiceHistory(idv){const r=state.maintenanceRecords.find(x=>x.id===idv),car=state.vehicles.find(v=>v.id===r?.vehicleId);if(!r)return;const task=car&&maintenancePlan(car).find(x=>x.id===r.taskId);openSheet(`<h2 id="sheetTitle">${esc(task?.name||r.taskId)}</h2><p class="muted">${fmtDate(r.date)} · ${r.mileage!=null?`${fmtNumber(r.mileage)} km`:"Sin kilometraje"}</p>${r.workshop?`<p><strong>Taller:</strong> ${esc(r.workshop)}</p>`:""}${r.cost!=null?`<p><strong>Coste:</strong> ${new Intl.NumberFormat("es-ES",{style:"currency",currency:"EUR"}).format(r.cost)}</p>`:""}${r.notes?`<p>${esc(r.notes)}</p>`:""}<button class="button danger" data-delete-service>Eliminar registro</button>`);sheetContent.querySelector("[data-delete-service]").onclick=()=>{if(!confirm("¿Eliminar este mantenimiento?"))return;state.maintenanceRecords=state.maintenanceRecords.filter(x=>x.id!==idv);saveState("Registro eliminado");closeSheet();renderHistory()}}

function openCarForm(editId=null){const existing=state.vehicles.find(v=>v.id===editId),brands=Object.keys(VEHICLES),bodyTypes=["5 puertas","3 puertas","Fastback","Wagon/Familiar","Sedán","SUV","Monovolumen","Cabrio"];openSheet(`<h2 id="sheetTitle">${existing?"Editar vehículo":"Añadir vehículo"}</h2><p class="muted">Selecciona una variante verificada cuando exista. Lo que no sepamos quedará marcado como manual.</p><form id="carForm" class="form-grid"><label class="field"><span>Apodo (opcional)</span><input name="nickname" maxlength="32" value="${esc(existing?.nickname||"")}" placeholder="Mi i30"></label><div class="two-cols"><label class="field"><span>Marca</span><select name="brand" id="brandSelect">${brands.map(b=>`<option ${b===existing?.brand?"selected":""}>${b}</option>`).join("")}</select></label><label class="field"><span>Modelo</span><select name="model" id="modelSelect"></select></label></div><div class="two-cols"><label class="field"><span>Año</span><select name="year" id="yearSelect"></select></label><label class="field"><span>Combustible</span><select name="fuel" id="fuelSelect"></select></label></div><label class="field" id="variantField"><span>Motor y versión</span><select name="variantId" id="variantSelect"></select><small class="muted">Las carrocerías tienen identificadores únicos en v2.</small></label><div class="two-cols"><label class="field"><span>Potencia (CV)</span><input required name="power" id="powerInput" type="number" min="1" max="2000" value="${existing?.power||""}"></label><label class="field"><span>Cambio</span><select name="transmission" id="transmissionSelect"><option value="manual">Manual</option><option value="automatic">Automático</option></select></label></div><div class="two-cols"><label class="field"><span>Turbo</span><select name="turbo" id="turboSelect"><option value="unknown">No lo sé</option><option value="yes">Sí</option><option value="no">No / atmosférico</option></select></label><label class="field"><span>Carrocería</span><select name="body"><option value="">Sin especificar</option>${bodyTypes.map(b=>`<option ${b===existing?.body?"selected":""}>${b}</option>`).join("")}</select></label></div><div class="two-cols"><label class="field"><span>Código de motor</span><input name="engineCode" maxlength="24" value="${esc(existing?.engineCode||"")}" placeholder="Ej. G3LE"></label><label class="field"><span>Kilometraje</span><input required name="mileage" type="number" min="0" max="3000000" value="${existing?.mileage||0}"></label></div><div class="two-cols"><label class="field"><span>VIN / bastidor</span><input name="vin" maxlength="17" value="${esc(existing?.vin||"")}" placeholder="17 caracteres"></label><label class="field"><span>Matrícula</span><input name="plate" maxlength="10" value="${esc(existing?.plate||"")}" placeholder="1234 ABC"></label></div><label class="field"><span>Color</span><input name="color" maxlength="40" value="${esc(existing?.color||"")}"></label><button class="button accent">${existing?"Guardar cambios":"Añadir al garaje"}</button></form>`);
  const brand=sheetContent.querySelector("#brandSelect"),model=sheetContent.querySelector("#modelSelect"),year=sheetContent.querySelector("#yearSelect"),fuel=sheetContent.querySelector("#fuelSelect"),variant=sheetContent.querySelector("#variantSelect"),power=sheetContent.querySelector("#powerInput"),transmission=sheetContent.querySelector("#transmissionSelect"),turbo=sheetContent.querySelector("#turboSelect");
  const updateVariants=()=>{const ms=variantsFor(brand.value,model.value,year.value,fuel.value);variant.innerHTML=`<option value="">Configurar manualmente</option>${ms.map(v=>`<option value="${esc(v.id)}">${esc(v.generation)} · ${esc(v.engine)} · ${esc(v.gearbox)}</option>`).join("")}`;if(existing?.variantId&&ms.some(v=>v.id===existing.variantId))variant.value=existing.variantId};
  const updateFuels=()=>{const ms=variantsFor(brand.value,model.value,year.value),available=[...new Set(ms.map(v=>v.fuel))],old=existing?.fuel||fuel.value;fuel.innerHTML=(available.length?available:Object.keys(FUELS)).map(k=>`<option value="${k}">${esc(FUELS[k])}</option>`).join("");if([...fuel.options].some(o=>o.value===old))fuel.value=old;updateVariants()};
  const updateYears=()=>{year.innerHTML=yearsForModel(brand.value,model.value).map(y=>`<option ${Number(existing?.year)===y?"selected":""}>${y}</option>`).join("");updateFuels()};
  const updateModels=()=>{model.innerHTML=Object.keys(VEHICLES[brand.value]).map(m=>`<option ${m===existing?.model?"selected":""}>${esc(m)}</option>`).join("");updateYears()};
  brand.onchange=updateModels;model.onchange=updateYears;year.onchange=updateFuels;fuel.onchange=updateVariants;variant.onchange=()=>{const s=VARIANTS.find(v=>v.id===variant.value);if(s){fuel.value=s.fuel;power.value=s.power;transmission.value=s.transmission;turbo.value=s.turbo}};updateModels();if(existing){transmission.value=existing.transmission||"manual";turbo.value=existing.turbo||"unknown";setTimeout(()=>{if(existing.variantId)variant.value=existing.variantId},0)}
  sheetContent.querySelector("#carForm").onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.vin=data.vin.trim().toUpperCase();data.plate=data.plate.trim().toUpperCase().replace(/\s+/g,"");if(data.vin&&!/^[A-HJ-NPR-Z0-9]{17}$/.test(data.vin)){showToast("El VIN debe tener 17 caracteres válidos");return}if(data.plate&&!validSpanishPlate(data.plate)){showToast("Revisa el formato de la matrícula");return}const spec=VARIANTS.find(v=>v.id===data.variantId),verified=spec?{generation:spec.generation,engine:spec.engine,gearbox:spec.gearbox,tech:spec.tech,baseFuel:spec.baseFuel,power:spec.power,transmission:spec.transmission,turbo:spec.turbo,catalogued:true}: {catalogued:false,tech:existing?.tech||[]};const car={...(existing||{id:id()}),...data,...verified,year:Number(data.year),power:Number(spec?.power||data.power),mileage:Number(data.mileage),updatedAt:new Date().toISOString()};if(existing)state.vehicles=state.vehicles.map(v=>v.id===existing.id?car:v);else state.vehicles.push(car);state.selectedVehicleId=car.id;saveState(existing?"Vehículo actualizado":"Coche añadido");closeSheet();render()}
}
function openCarDetails(carId){const v=state.vehicles.find(x=>x.id===carId);if(!v)return;state.selectedVehicleId=v.id;saveState();const comps=componentsFor(v);openSheet(`<p class="eyebrow">${v.catalogued?"Versión de catálogo":"Configuración manual"}</p><h2 id="sheetTitle">${esc(vehicleName(v))}</h2><p class="muted">${esc(v.nickname?`${v.brand} ${v.model} · ${vehicleDetails(v)}`:vehicleDetails(v))}</p><div class="summary-grid"><div class="summary-card"><strong>${fmtNumber(v.mileage)}</strong><small>kilómetros</small></div><div class="summary-card"><strong>${v.power||"—"}</strong><small>CV</small></div><div class="summary-card"><strong>${state.diagnosisHistory.filter(x=>x.vehicleId===v.id).length}</strong><small>diagnósticos</small></div></div><div class="selector-list">${v.generation?`<div class="selector-card"><strong>${esc(v.generation)}</strong><small>${esc(v.engine||"")} · ${esc(v.gearbox||"")}</small></div>`:""}${v.engineCode?`<div class="selector-card"><strong>${esc(v.engineCode)}</strong><small>Código de motor declarado</small></div>`:""}${v.vin?`<div class="selector-card"><strong>${esc(v.vin)}</strong><small>VIN</small></div>`:""}${v.plate?`<div class="selector-card"><strong>${esc(formatPlate(v.plate))}</strong><small>Matrícula</small></div>`:""}</div><div class="section-head"><div><h3>Sistemas confirmados</h3><p>Solo se muestran los declarados por la variante.</p></div></div>${comps.length?`<div class="component-grid">${comps.map(c=>`<div class="component-pill"><span>✓</span>${esc(c)}</div>`).join("")}</div>`:`<p class="muted">Perfil genérico: confirma motor y equipamiento antes de confiar en el filtrado.</p>`}<div class="button-row"><button class="button accent" data-diagnose>Diagnosticar</button><button class="button ghost" data-edit>Editar</button></div><div class="button-row"><button class="button ghost" data-mileage>Actualizar km</button><button class="button ghost" data-maint>Mantenimiento</button></div><button class="button danger" style="margin-top:12px" data-delete>Eliminar del garaje</button>`);sheetContent.querySelector("[data-diagnose]").onclick=()=>{closeSheet();diagnosis=null;setView("diagnosis")};sheetContent.querySelector("[data-edit]").onclick=()=>openCarForm(v.id);sheetContent.querySelector("[data-mileage]").onclick=()=>openMileageForm(v);sheetContent.querySelector("[data-maint]").onclick=()=>{closeSheet();setView("maintenance")};sheetContent.querySelector("[data-delete]").onclick=()=>{if(!confirm(`¿Eliminar ${vehicleName(v)} y sus registros?`))return;state.vehicles=state.vehicles.filter(x=>x.id!==v.id);state.maintenanceRecords=state.maintenanceRecords.filter(x=>x.vehicleId!==v.id);state.diagnosisHistory=state.diagnosisHistory.filter(x=>x.vehicleId!==v.id);state.selectedVehicleId=state.vehicles[0]?.id||null;saveState("Vehículo eliminado");closeSheet();render()}}
function openVehiclePicker(){openSheet(`<h2 id="sheetTitle">Selecciona un vehículo</h2><div class="selector-list">${state.vehicles.map(v=>`<button class="selector-card ${v.id===state.selectedVehicleId?"active":""}" data-pick="${esc(v.id)}"><strong>${esc(vehicleName(v))}</strong><small>${esc(vehicleDetails(v))}</small></button>`).join("")}</div>`);sheetContent.querySelectorAll("[data-pick]").forEach(b=>b.onclick=()=>{state.selectedVehicleId=b.dataset.pick;saveState();diagnosis=null;closeSheet();renderDiagnosis()})}

function validSpanishPlate(p){return/^(\d{4}[BCDFGHJKLMNPRSTVWXYZ]{3}|[A-Z]{1,2}\d{4}[A-Z]{1,2}|[A-Z]\d{4}[A-Z]{2})$/.test(p)}
function formatPlate(p){return/^\d{4}/.test(p)?`${p.slice(0,4)} ${p.slice(4)}`:p}
const WMI={WVW:"Volkswagen",WVG:"Volkswagen",VSS:"SEAT",TMB:"Škoda",WAU:"Audi",WBA:"BMW",WBS:"BMW M",WDD:"Mercedes-Benz",VF1:"Renault",VF3:"Peugeot",VF7:"Citroën",TMA:"Hyundai",KMH:"Hyundai",W0L:"Opel",WF0:"Ford",ZFA:"Fiat",ZAR:"Alfa Romeo",JHM:"Honda",JTD:"Toyota",JN1:"Nissan"};
function localVinDecode(vin){return{vin,make:WMI[vin.slice(0,3)]||"Fabricante no identificado",modelYear:"El año europeo debe confirmarse con ficha técnica",source:"Decodificación local del WMI"}}
async function decodeVin(vin){const local=localVinDecode(vin);try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000),res=await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValuesExtended/${encodeURIComponent(vin)}?format=json`,{signal:controller.signal});clearTimeout(timer);if(!res.ok)throw Error();const x=(await res.json()).Results?.[0];if(!x)throw Error();const engine=x.EngineModel||x.DisplacementL?`${x.EngineModel||""} ${x.DisplacementL?`${x.DisplacementL} L`:""}`.trim():"No disponible";return{vin,make:x.Make||local.make,model:x.Model||"No disponible",year:x.ModelYear||"No disponible",engine,fuel:x.FuelTypePrimary||"No disponible",source:"NHTSA vPIC; cobertura europea limitada"}}catch{return local}}
function openIdentify(){
  openSheet(`<h2 id="sheetTitle">Identificar vehículo</h2><p class="muted">Usa el VIN para datos básicos. Para matrícula española, MotorClaro te lleva a la consulta oficial: no accede a titulares ni bases privadas.</p><form id="identifyForm" class="form-grid"><label class="field"><span>VIN / bastidor</span><input name="vin" maxlength="17" placeholder="17 caracteres"></label><button class="button accent">Decodificar VIN</button></form><div id="vinResult"></div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><form id="plateForm" class="form-grid"><label class="field"><span>Matrícula española</span><input name="plate" maxlength="10" placeholder="1234 ABC"></label><button class="button ghost">Validar y abrir consulta DGT</button></form><div class="notice info"><span>i</span><div><strong>Sobre TecDoc y Amazon</strong>TecDoc admite VIN/VRM con contrato profesional. Amazon Rekognition puede leer caracteres de una foto, pero no identifica por sí solo marca, modelo o motor.</div></div>`);
  sheetContent.querySelector("#identifyForm").onsubmit=async e=>{e.preventDefault();const vin=new FormData(e.target).get("vin").trim().toUpperCase();if(!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin)){showToast("Introduce un VIN válido de 17 caracteres");return}const out=sheetContent.querySelector("#vinResult");out.innerHTML=`<p class="muted">Consultando…</p>`;const d=await decodeVin(vin);out.innerHTML=`<div class="selector-card" style="margin-top:16px"><strong>${esc(d.make)} ${esc(d.model||"")}</strong><small>${esc(d.year||d.modelYear||"")} · ${esc(d.engine||"")}</small><small>${esc(d.source)}</small></div>`};
  sheetContent.querySelector("#plateForm").onsubmit=e=>{e.preventDefault();const p=new FormData(e.target).get("plate").trim().toUpperCase().replace(/\s+/g,"");if(!validSpanishPlate(p)){showToast("La matrícula no tiene un formato español válido");return}window.open("https://sede.dgt.gob.es/es/vehiculos/informe-de-vehiculo/","_blank","noopener,noreferrer")};
}

function openSettings(){openSheet(`<h2 id="sheetTitle">Perfil y ajustes</h2><form id="profileForm" class="form-grid"><label class="field"><span>Nombre</span><input name="name" maxlength="40" value="${esc(state.profile.name)}"></label><button class="button">Guardar nombre</button></form><div class="setting-card"><h3>Apariencia</h3><div class="segmented">${["auto","light","dark"].map(t=>`<button data-theme="${t}" class="${state.settings.theme===t?"active":""}">${({auto:"Sistema",light:"Claro",dark:"Oscuro"})[t]}</button>`).join("")}</div></div><div class="setting-card"><h3>Copia de seguridad</h3><p>Exporta garaje, historial y ajustes. El archivo no sale de tu dispositivo salvo que tú lo compartas.</p><div class="button-row"><button class="button ghost" data-export>Exportar JSON</button><button class="button ghost" data-import>Importar JSON</button></div></div><div class="setting-card"><h3>Fuentes de datos</h3><p><strong>Catálogo local:</strong> 633 combinaciones de 26 modelos.</p><p><strong>VIN:</strong> decodificación básica y consulta NHTSA sin clave; cobertura europea limitada.</p><p><strong>Europa profesional:</strong> integración preparada para TecDoc VIN/VRM cuando exista contrato y backend seguro.</p><p><strong>Matrícula española:</strong> acceso a la consulta oficial DGT. No se consultan titulares ni bases obtenidas por scraping.</p></div><div class="setting-card"><h3>Privacidad</h3><p>Los datos se guardan en este navegador. MotorClaro no envía tu historial a un servidor propio.</p><button class="button danger" data-wipe>Borrar todos mis datos</button></div><p class="privacy-note">MotorClaro ${APP_VERSION}. Orientación informativa; no sustituye un taller ni la documentación oficial.</p>`);sheetContent.querySelector("#profileForm").onsubmit=e=>{e.preventDefault();state.profile.name=String(new FormData(e.target).get("name")).trim();saveState("Perfil guardado");render();closeSheet()};sheetContent.querySelectorAll("[data-theme]").forEach(b=>b.onclick=()=>{state.settings.theme=b.dataset.theme;saveState();applyTheme();openSettings()});sheetContent.querySelector("[data-export]").onclick=exportData;sheetContent.querySelector("[data-import]").onclick=()=>importFile.click();sheetContent.querySelector("[data-wipe]").onclick=()=>{if(!confirm("¿Borrar vehículos, diagnósticos, mantenimientos y ajustes? Esta acción no se puede deshacer."))return;state=defaults();saveState("Datos borrados");applyTheme();closeSheet();render()}}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),appVersion:APP_VERSION},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`motorclaro-copia-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast("Copia preparada")}
importFile.onchange=async()=>{const file=importFile.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text()),next=migrate(parsed);if(!confirm(`Importar ${next.vehicles.length} vehículos y sustituir los datos actuales?`))return;state=next;saveState("Copia importada");applyTheme();closeSheet();render()}catch{showToast("El archivo no es una copia válida de MotorClaro")}finally{importFile.value=""}}

function openSheet(html){lastFocus=document.activeElement;sheetContent.innerHTML=html;sheet.classList.remove("hidden");document.body.style.overflow="hidden";requestAnimationFrame(()=>sheetContent.querySelector("input,select,textarea,button")?.focus())}
function closeSheet(){sheet.classList.add("hidden");document.body.style.overflow="";lastFocus?.focus?.();lastFocus=null}
function showToast(message){toast.textContent=message;toast.classList.remove("hidden");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.add("hidden"),2600)}
function bindCommon(){main.querySelectorAll("[data-action='add-car']").forEach(b=>b.onclick=()=>openCarForm());main.querySelector("[data-action='diagnose']")?.addEventListener("click",()=>setView("diagnosis"));main.querySelector("[data-action='garage']")?.addEventListener("click",()=>setView("garage"));main.querySelector("[data-action='identify']")?.addEventListener("click",openIdentify);main.querySelectorAll("[data-vehicle]").forEach(b=>b.onclick=()=>openCarDetails(b.dataset.vehicle));main.querySelector("[data-action='install']")?.addEventListener("click",installApp)}
async function installApp(){if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;render()}

document.querySelectorAll(".nav-item").forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelector("[data-go='home']").onclick=()=>setView("home");document.querySelector("#profileButton").onclick=openSettings;sheet.addEventListener("click",e=>{if(e.target===sheet)closeSheet()});sheet.addEventListener("click",e=>{if(e.target.closest("[data-close]"))closeSheet()});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!sheet.classList.contains("hidden"))closeSheet();if(e.key==="Tab"&&!sheet.classList.contains("hidden")){const focusable=[...sheet.querySelectorAll("button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]")];if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installPrompt=e;render()});window.addEventListener("appinstalled",()=>{installPrompt=null;showToast("MotorClaro instalada")});matchMedia("(prefers-color-scheme: dark)").addEventListener?.("change",()=>{if(state.settings.theme==="auto")applyTheme()});
if("serviceWorker"in navigator)window.addEventListener("load",async()=>{try{const reg=await navigator.serviceWorker.register("./sw.js");reg.addEventListener("updatefound",()=>{const worker=reg.installing;worker?.addEventListener("statechange",()=>{if(worker.state==="installed"&&navigator.serviceWorker.controller)document.querySelector("#updateBanner").classList.remove("hidden")})});navigator.serviceWorker.addEventListener("controllerchange",()=>location.reload())}catch{showToast("La app funciona, pero el modo sin conexión no está disponible")}});document.querySelector("#reloadUpdate").onclick=async()=>{const reg=await navigator.serviceWorker.getRegistration();reg?.waiting?.postMessage({type:"SKIP_WAITING"})};
const requestedView=new URLSearchParams(location.search).get("view");
if(["home","garage","diagnosis","maintenance","history"].includes(requestedView))currentView=requestedView;
applyTheme();setView(currentView);
